import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { WorkerPool } from "../src/transcode/pool.ts";
import { renditionsFor, type Rendition } from "../src/transcode/renditions.ts";
import { TranscodeService, type Encoder } from "../src/transcode/service.ts";

// Fake encoder: takes a few event-loop turns per rendition; fails on corrupt sources
// and on any rendition listed in `badRenditions`.
function encoder(badRenditions: string[] = []): Encoder & { running: number; peak: number } {
    const enc = {
        running: 0,
        peak: 0,
        async encode(videoId: string, sourceUri: string, r: Rendition) {
            enc.running++;
            enc.peak = Math.max(enc.peak, enc.running);
            try {
                for (let i = 0; i < 3; i++) await tick();
                if (sourceUri.includes("corrupt")) throw new Error(`moov atom not found in ${sourceUri}`);
                if (badRenditions.includes(r.name)) throw new Error(`encoder crashed on ${r.name}`);
                return `s3://vod/${videoId}/${r.name}/index.m3u8`;
            } finally {
                enc.running--;
            }
        },
    };
    return enc;
}

async function within<T>(ms: number, work: Promise<T>): Promise<T> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error(`still waiting after ${ms}ms (pool stuck?)`)), ms);
    });
    try {
        return await Promise.race([work, timeout]);
    } finally {
        clearTimeout(timer);
    }
}

test("renditions never upscale the source", () => {
    assert.deepEqual(renditionsFor(720).map((r) => r.name), ["720p", "480p", "360p", "240p"]);
    assert.deepEqual(renditionsFor(1440).length, 5);
    assert.deepEqual(renditionsFor(200), []);
});

test("a 1080p upload gets every rendition, never more than the pool size at once", async () => {
    const enc = encoder();
    const service = new TranscodeService(new WorkerPool(2), enc);
    const status = await within(500, service.process({ videoId: "v1", sourceUri: "s3://in/v1.mp4", height: 1080 }));
    assert.equal(status.state, "ready");
    assert.equal(Object.keys(status.outputs).length, 5);
    assert.equal(status.outputs["360p"], "s3://vod/v1/360p/index.m3u8");
    assert.equal(enc.peak, 2);
});

test("a corrupt upload is reported as failed", async () => {
    const service = new TranscodeService(new WorkerPool(3), encoder());
    const status = await within(500, service.process({ videoId: "v2", sourceUri: "s3://in/corrupt.mov", height: 480 }));
    assert.deepEqual(status, { videoId: "v2", state: "failed", outputs: {}, failed: ["480p", "360p", "240p"] });
});

test("when one rendition crashes the video is still published with the rest", async () => {
    const service = new TranscodeService(new WorkerPool(2), encoder(["720p"]));
    const status = await within(500, service.process({ videoId: "v3", sourceUri: "s3://in/v3.mp4", height: 720 }));
    assert.equal(status.state, "ready");
    assert.deepEqual(status.failed, ["720p"]);
    assert.deepEqual(Object.keys(status.outputs), ["480p", "360p", "240p"]);
});

test("uploads after a corrupt one are still transcoded", async () => {
    const pool = new WorkerPool(2);
    const service = new TranscodeService(pool, encoder());
    await within(500, service.process({ videoId: "bad", sourceUri: "s3://in/corrupt.mp4", height: 360 }));
    console.log("pool after the corrupt upload:", pool.stats());
    const status = await within(500, service.process({ videoId: "good", sourceUri: "s3://in/good.mp4", height: 360 }));
    assert.equal(status.state, "ready");
});

test("failed tasks give their worker back", async () => {
    const pool = new WorkerPool(3);
    const failing = Array.from({ length: 4 }, (_, i) => pool.submit(async () => {
        await tick();
        throw new Error(`job ${i} failed`);
    }));
    const results = await within(500, Promise.allSettled(failing));
    assert.ok(results.every((r) => r.status === "rejected"));
    assert.deepEqual(pool.stats(), { size: 3, active: 0, queued: 0 });
});

test("onIdle waits for queued work, including work that fails", async () => {
    const pool = new WorkerPool(1);
    const done: string[] = [];
    pool.submit(async () => { await tick(); done.push("a"); });
    pool.submit(async () => { await tick(); throw new Error("b failed"); }).catch(() => done.push("b"));
    pool.submit(async () => { await tick(); done.push("c"); });
    await within(500, pool.onIdle());
    assert.deepEqual(done, ["a", "b", "c"]);
});
